def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    temp = ""

    # Handle potential invalid inputs
    if not isinstance(paren_string, str) or " " in paren_string:
        raise ValueError("Invalid input. Input should be a non-empty string without spaces.")

    # Iterate through each character in the input string
    for char in paren_string:
        # If the character is an open parenthesis
        if char == '(':
            temp += char
        # If the character is a close parenthesis
        elif char == ')':
            if temp:
                result.append(temp + ')')
                temp = ""

    # Return the result list
    return result

