def max_product(num_str: str, N: int, K: int) -> int:
    if K > min(N // 2, len(num_str) - N // 2):
        return -1  # Not enough spaces to insert K multiplication signs
    if N <= 1 or K == 0:
        return int(num_str)  # No multiplication signs needed or one-digit number

    max_product = int(num_str[0])
    max_so_far = max_product
    for i in range(1, N):
        if i == K:
            break
        curr_product = int(num_str[i]) if i > 0 else 1
        max_so_far *= curr_product
        max_product = max(max_product, max_so_far)

    return max(max_product, int(num_str[-1]))

