def optimize_seating(M, N, K, L, D, chatting_pairs):
    if M < K + 1 or N < L + 1:
        return "Error: Classroom size is too small to accommodate aisles."

    row_aisles = {i: 0 for i in range(K + 1)}
    col_aisles = {i: 0 for i in range(L + 1)}

    for (x1, y1, x2, y2) in chatting_pairs:
        if x1 == x2:  # Vertical chatting pair
            if y1 == y2:  # Chatting onboard, ignore
                continue
            if row_aisles[x1] < col_aisles[y2]:
                col_aisles[y2] += 1
            elif row_aisles[x1] > col_aisles[y2]:
                row_aisles[x1] += 1
        elif y1 == y2:  # Horizontal chatting pair
            if x1 == x2:  # Chatting onboard, ignore
                continue
            if row_aisles[x1] < col_aisles[y1]:
                col_aisles[y1] += 1
            elif row_aisles[x1] > col_aisles[y1]:
                row_aisles[x1] += 1
        else:  # Diagonal chatting pairs
            if x1 == x2:  # Column chatting pair
                if y1 == y2 + 1 or y1 == y2 - 1:
                    idx = y1 if y1 < y2 else y2
                    if row_aisles[x1] < col_aisles[idx]:
                        col_aisles[idx] += 1
                        # Ensure total number of aisles does not exceed K or L
                        if idx > col_aisles[-1]:
                            row_aisles[x1] -= 1
                    elif row_aisles[x1] > col_aisles[idx]:
                        row_aisles[x1] -= 1
                        # Ensure total number of aisles does not exceed K or L
                        if idx < row_aisles[-1]:
                            col_aisles[idx] += 1
                else:
                    return "Error: Diagonal chats require valid column index."
            elif y1 == y2:  # Row chatting pair
                if x1 + 1 == x2 or x1 - 1 == x2:
                    idx = x1 if x1 < x2 else x2
                    if col_aisles[y1] < row_aisles[idx]:
                        row_aisles[idx] += 1
                        # Ensure total number of aisles does not exceed K or L
                        if idx > row_aisles[-1]:
                            row_aisles[idx] -= 1
                    elif col_aisles[y1] > row_aisles[idx]:
                        col_aisles[y1] -= 1
                        # Ensure total number of aisles does not exceed K or L
                        if idx < col_aisles[-1]:
                            row_aisles[idx] += 1
                else:
                    return "Error: Diagonal chats require valid row index."

    optimal_row = min(row_aisles, default=-1)
    optimal_col = min(col_aisles, default=-1)

    if optimal_row == -1 or optimal_col == -1:
        return "Error: No alternate arrangements found."

    row_str = [str(i) for i in row_aisles.keys() if i < optimal_row]
    col_str = [str(i) for i in col_aisles.keys() if i < optimal_col]

