def max_energy(beads):
    n = len(beads)
    # Helper function to compute the maximum energy starting from bead i with k beads
    def max_energy_recurse(i, k):
        if k == 0 or k > n // 2:
            return 0
        max_energy_list = []
        for j in range(i, i + k):
            if beads[j] == beads[(j + 1) % n]:
                max_energy_list.append(max_energy_recurse(j + 1, k - 1))
            else:
                max_energy_list.append(0)
        return max(max_energy_list) + beads[i] * beads[(i + k - 1) % n]

    # Unpack the list of beads into separate values and then solve for the maximum energy
    elems = [beads[i] for i in range(n)]
    max_i = max(range(n), key=lambda i: (abs(i - n // 2) + sum(elems[i:i + int(n // 2)]), elems[i]))
    return max_energy_recurse(max_i, int(n // 2))

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if not isinstance(n, int) or not isinstance(coeffs, list):
        raise ValueError("Invalid input: n must be an integer and coeffs must be a list")

    if n == 0:
        return "-0" if coeffs else ""

    terms = []
    for degree, coeff in enumerate(coeffs[::-1]):  # Reverse coeffs for natural degree order
        if coeff > 0:
            sign = "+" if degree != 0 else ""
        else:
            sign = ""

        if coeff != 1 or degree == 0:  # No leading 1 for constant term
            term = str(abs(coeff)) + "x"
        elif degree == 1 and len(coeffs) == 1:
            term = "x"
        else:
            term = ""

        if term:
            terms.append(term)

    return sign + " ".join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    mapping = {}
    original_length = len(original)

    # Edge case: both encoded and original should have the same length
    if len(encoded) != original_length:
        return "Failed"

    # Map each encoded letter to its original letter
    for i in range(original_length):
        mapping[original[i]] = encoded[i]

    # Iterate through each letter in the message
    for letter in message:
        # If the letter is not found in the mapping, returnFailed
        if letter not in mapping:
            return "Failed"

    # Decode the message using the mapping
    decoded_message = ''.join(mapping[letter] for letter in message)
    return decoded_message

def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1.")
    factor = 2
    while factor * factor <= n:
        if n % factor:
            factor += 1
        else:
            n //= factor
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    if k == 1:
        return max(0, n - x)

    partitions = 0
    for a in range(1, n - k * x + 1):
        partitions += count_partitions(n - a, k - 1, x)

    return partitions

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n <= 0:
        return 0

    if last in memo:
        return memo[last]

    memo[last] = 1  # Starting sequence with 'n'
    if last > 1:
        for i in range(1, n):
            if i <= last // 2:
                memo[last] += count_sequences(n, i, memo)

    return memo[last]

