def is_prime(num: int) -> bool:
    # Check for edge cases
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False

    # Start checking from 5 and go up in steps of 6
    for i in range(5, int(num**0.5) + 1, 6):
        if num % i == 0 or num % (i + 2) == 0:
            return False

    return True

def generate_numbers(n, rules) -> int:
    if not rules:
        return 1  # Base case: Single digit rule, all permutations of n
    unique_numbers = {n}
    queue = [n]
    while queue:
        current_number = queue.pop(0)
        new_numbers = {int(str(current_number).replace(digit, new_digit)) for digit, new_digit in rules}
        unique_numbers.update(new_numbers)
        queue.extend(new_numbers)
    return len(unique_numbers)

