def catalan_number(n: int) -> int:
    # Edge cases: the first and last Catalan numbers are 1
    if n <= 1:
        return 1

    # Initialize an array to store Catalan numbers up to n
    catalan = [0] * (n + 1)
    catalan[0], catalan[1] = 1, 1

    # Fill the array using the recursive formula
    for i in range(2, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]

    return catalan[n]

