def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a list to store the maximum volume seen at each step
    dp = [0] * (V + 1)

    # Iterate over the volumes of each item
    for volume in volumes:
        for current_capacity in range(V, volume - 1, -1):
            # Update the maximum volume at the current capacity
            dp[current_capacity] = max(dp[current_capacity], dp[current_capacity - volume] + volume)

    # The minimum remaining space is the total capacity minus the maximum volume
    # occupied among the given items
    return V - max(dp)

